nodes.command:
node -e "
const fs = require('fs');
const path = require('path');

const configDir = '${inputs.project_root}/src/data/vfx';
if (!fs.existsSync(configDir)) fs.mkdirSync(configDir, { recursive: true });

const config = {
  key: '${inputs.vfx_name}',
  type: '${inputs.vfx_type}',
  spritesheet: 'vfx_${inputs.vfx_name}',
  frameConfig: {
    frameWidth: ${inputs.width},
    frameHeight: ${inputs.height},
    endFrame: ${inputs.frame_count} - 1
  },
  animConfig: {
    frameRate: 12,
    repeat: ${inputs.loop} ? -1 : 0
  },
  meta: {
    created_at: new Date().toISOString(),
    asset_mode: 'production'
  }
};

const configPath = path.join(configDir, '${inputs.vfx_name}.json');
fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
console.log('Phaser VFX config generated:', configPath);
"

node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/asset-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { backgrounds: {}, characters: {}, objects: {}, animations: {}, vfx: {} };

registry.vfx = registry.vfx || {};
registry.vfx['${inputs.vfx_name}'] = {
  type: '${inputs.vfx_type}',
  spritesheet: 'assets/images/spritesheets/vfx_${inputs.vfx_name}.png',
  config: 'src/data/vfx/${inputs.vfx_name}.json',
  frames: ${inputs.frame_count},
  dimensions: { width: ${inputs.width}, height: ${inputs.height} },
  loop: ${inputs.loop},
  format: 'PNG',
  asset_mode: 'production',
  updated_at: new Date().toISOString()
};

fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Asset registry updated for VFX:', '${inputs.vfx_name}');
"

body.msg:
task_id=${inputs.task_id}
role=L3_vfx_artist
vfx=${inputs.vfx_name}
frames=${inputs.frame_count}
format=PNG
status=SUCCESS
